const data = $input.item.json;
const empresa = $('Loop por Empresa').item.json;
const clientes = Array.isArray(data) ? data : (data.datos || data.value || [data]);
const c = clientes[0] || {};
return [{ json: {
  empresaId: empresa.id || empresa.codigo || empresa.Codigo,
  empresaNombre: empresa.nombre || empresa.Nombre || c.NombreFiscal || 'Sin nombre',
  email: c.Mail || c.mail || '',
  cif: c.CIF || empresa.cif || '',
  direccion: c.Direccion || '',
  provincia: c.Provincia || 'Madrid'
}}];

const empresa = $('Extraer Datos Empresa').item.json;
const subcuentasRaw = $('GET Subcuentas (Plan de Cuentas)').item.json;
const facturasRaw = $('GET Facturas del Año').item.json;
const apuntesRaw = $('GET Apuntes del Año').item.json;
const tokens = $('Guardar Tokens').item.json;

const subcuentas = Array.isArray(subcuentasRaw) ? subcuentasRaw : (subcuentasRaw.datos || subcuentasRaw.value || []);
const facturas = Array.isArray(facturasRaw) ? facturasRaw : (facturasRaw.datos || facturasRaw.value || []);
const apuntes = Array.isArray(apuntesRaw) ? apuntesRaw : (apuntesRaw.datos || apuntesRaw.value || []);

// Función para obtener saldo de un grupo de cuentas por prefijo
const saldoGrupo = (prefijos) => {
  return subcuentas
    .filter(s => prefijos.some(p => String(s.Codigo || '').startsWith(p)))
    .reduce((sum, s) => sum + (parseFloat(s.Saldo || 0)), 0);
};

const debeGrupo = (prefijos) => subcuentas
  .filter(s => prefijos.some(p => String(s.Codigo || '').startsWith(p)))
  .reduce((sum, s) => sum + parseFloat(s.Debe || 0), 0);

const haberGrupo = (prefijos) => subcuentas
  .filter(s => prefijos.some(p => String(s.Codigo || '').startsWith(p)))
  .reduce((sum, s) => sum + parseFloat(s.Haber || 0), 0);

// ========== CUENTA DE RESULTADOS (PyG) ==========
// Grupo 7: Ingresos
const ventasServicios = Math.abs(saldoGrupo(['700','701','702','703','704','705']));
const otrosIngresos = Math.abs(saldoGrupo(['706','708','709','740','747','75']));
const ingresosFinancieros = Math.abs(saldoGrupo(['76']));
const totalIngresos = ventasServicios + otrosIngresos;

// Grupo 6: Gastos
const aprovisionamientos = Math.abs(saldoGrupo(['60','61']));
const gastosPersonal = Math.abs(saldoGrupo(['64']));
const otrosGastosExplotacion = Math.abs(saldoGrupo(['62','63','65','68']));
const amortizaciones = Math.abs(saldoGrupo(['68']));
const gastosFinancieros = Math.abs(saldoGrupo(['66']));
const totalGastos = aprovisionamientos + gastosPersonal + otrosGastosExplotacion;

const ebit = totalIngresos - totalGastos;
const resultadoAntesImpuestos = ebit + ingresosFinancieros - gastosFinancieros;
const impuestoSociedades = resultadoAntesImpuestos > 0 ? resultadoAntesImpuestos * 0.25 : 0;
const resultadoNeto = resultadoAntesImpuestos - impuestoSociedades;

const margenNeto = totalIngresos > 0 ? ((resultadoNeto / totalIngresos) * 100).toFixed(1) : 0;
const ratioGastos = totalIngresos > 0 ? ((totalGastos / totalIngresos) * 100).toFixed(1) : 0;
const ebitda = ebit + amortizaciones;
const margenEBITDA = totalIngresos > 0 ? ((ebitda / totalIngresos) * 100).toFixed(1) : 0;

// ========== BALANCE DE SITUACIÓN ==========
// ACTIVO
const inmovilizadoMaterial = Math.abs(saldoGrupo(['21','22','23']));
const inmovilizadoIntangible = Math.abs(saldoGrupo(['20']));
const inversionesFinancieras = Math.abs(saldoGrupo(['25','26']));
const activoNoCorriente = inmovilizadoMaterial + inmovilizadoIntangible + inversionesFinancieras;

const existencias = Math.abs(saldoGrupo(['30','31','32','33','34','35']));
const clientes = Math.abs(saldoGrupo(['430','431','432','433','440','441']));
const otrosDeudores = Math.abs(saldoGrupo(['44','46','47','48']));
const tesoreria = Math.abs(saldoGrupo(['57']));
const activoCorriente = existencias + clientes + otrosDeudores + tesoreria;
const totalActivo = activoNoCorriente + activoCorriente;

// PASIVO + PATRIMONIO NETO
const capitalSocial = Math.abs(saldoGrupo(['10','11','12']));
const reservas = Math.abs(saldoGrupo(['11']));
const resultadoEjercicio = resultadoNeto;
const patrimonioNeto = capitalSocial + reservas + resultadoEjercicio;

const deudasLargoPlazo = Math.abs(saldoGrupo(['15','16','17','18']));
const proveedores = Math.abs(saldoGrupo(['40','41']));
const acreedores = Math.abs(saldoGrupo(['41','43','46']));
const deudasCortoPlazo = Math.abs(saldoGrupo(['52','53','55']));
const aapp = Math.abs(saldoGrupo(['47']));
const pasivoCorriente = proveedores + acreedores + deudasCortoPlazo + aapp;
const totalPasivo = deudasLargoPlazo + pasivoCorriente + patrimonioNeto;

// ========== RATIOS ==========
const liquidez = pasivoCorriente > 0 ? (activoCorriente / pasivoCorriente).toFixed(2) : 'N/A';
const endeudamiento = totalActivo > 0 ? (((deudasLargoPlazo + pasivoCorriente) / totalActivo) * 100).toFixed(1) : 'N/A';
const rotacionActivo = totalActivo > 0 ? (totalIngresos / totalActivo).toFixed(2) : 'N/A';
const rentabilidadEconomica = totalActivo > 0 ? ((ebit / totalActivo) * 100).toFixed(1) : 'N/A';
const rentabilidadFinanciera = patrimonioNeto > 0 ? ((resultadoNeto / patrimonioNeto) * 100).toFixed(1) : 'N/A';
const fondoManiobra = (activoCorriente - pasivoCorriente).toFixed(2);

// ========== EVOLUCIÓN MENSUAL (facturas) ==========
const facturasPorMes = {};
facturas.forEach(f => {
  const fecha = f.Fecha || '';
  const mes = fecha.substring(5, 7);
  if (!mes) return;
  if (!facturasPorMes[mes]) facturasPorMes[mes] = { ingresos: 0, gastos: 0 };
  const importe = parseFloat(f.TotalFactura || 0);
  if (f.TipoAsiento === 1 || f.TipoFactura === 1) facturasPorMes[mes].ingresos += importe;
  else facturasPorMes[mes].gastos += importe;
});

const evolucion = Object.entries(facturasPorMes)
  .sort(([a], [b]) => a.localeCompare(b))
  .map(([mes, datos]) => ({
    mes: ['Ene','Feb','Mar','Abr','May','Jun','Jul','Ago','Sep','Oct','Nov','Dic'][parseInt(mes) - 1] || mes,
    ingresos: datos.ingresos.toFixed(2),
    gastos: datos.gastos.toFixed(2),
    resultado: (datos.ingresos - datos.gastos).toFixed(2)
  }));

const fmt = (n) => n.toLocaleString('es-ES', { minimumFractionDigits: 2, maximumFractionDigits: 2 }) + ' EUR';

return [{ json: {
  empresa: empresa.empresaNombre,
  cif: empresa.cif,
  email: empresa.email,
  direccion: empresa.direccion,
  provincia: empresa.provincia,
  nombreMes: tokens.nombreMes,
  year: tokens.year,
  trimestre: tokens.trimestre,
  // PyG
  ventasServicios: fmt(ventasServicios),
  otrosIngresos: fmt(otrosIngresos),
  totalIngresos: fmt(totalIngresos),
  aprovisionamientos: fmt(aprovisionamientos),
  gastosPersonal: fmt(gastosPersonal),
  otrosGastosExplotacion: fmt(otrosGastosExplotacion),
  amortizaciones: fmt(amortizaciones),
  totalGastos: fmt(totalGastos),
  ebit: fmt(ebit),
  ebitda: fmt(ebitda),
  ingresosFinancieros: fmt(ingresosFinancieros),
  gastosFinancieros: fmt(gastosFinancieros),
  resultadoAntesImpuestos: fmt(resultadoAntesImpuestos),
  impuestoSociedades: fmt(impuestoSociedades),
  resultadoNeto: fmt(resultadoNeto),
  margenNeto,
  margenEBITDA,
  ratioGastos,
  // Balance
  inmovilizadoMaterial: fmt(inmovilizadoMaterial),
  inmovilizadoIntangible: fmt(inmovilizadoIntangible),
  inversionesFinancieras: fmt(inversionesFinancieras),
  activoNoCorriente: fmt(activoNoCorriente),
  existencias: fmt(existencias),
  clientes: fmt(clientes),
  otrosDeudores: fmt(otrosDeudores),
  tesoreria: fmt(tesoreria),
  activoCorriente: fmt(activoCorriente),
  totalActivo: fmt(totalActivo),
  capitalSocial: fmt(capitalSocial),
  patrimonioNeto: fmt(patrimonioNeto),
  deudasLargoPlazo: fmt(deudasLargoPlazo),
  proveedores: fmt(proveedores),
  pasivoCorriente: fmt(pasivoCorriente),
  totalPasivo: fmt(totalPasivo),
  // Ratios
  liquidez,
  endeudamiento,
  rotacionActivo,
  rentabilidadEconomica,
  rentabilidadFinanciera,
  fondoManiobra: fmt(parseFloat(fondoManiobra)),
  // Evolución
  evolucion: JSON.stringify(evolucion),
  // Raw para prompt
  totalIngresosRaw: totalIngresos,
  resultadoNetoRaw: resultadoNeto
}}];

